//! L08-H: the GPU effect executor on the real headless Metal compositor,
//! compared with literals from the baseline oracle.
//!
//! `fixtures/scene-effect-gpu-pass/oracle.txt` was generated by
//! `tools/gen_scene_effect_gpu_pass_oracle.js` from the baseline
//! `color_adjust.wgsl`, `vignette.wgsl`, `blur.wgsl`, `blend.wgsl` and the
//! `run_one_effect` arms of `geometry-wasm/src/engine.rs` at fbe4b8a3: 24
//! stacks on 8x8..24x24 canvases, every texture write quantised to RGBA8. The
//! GPU result is the actual `Compositor::apply_effect_stack` /
//! `apply_effect_stack_into` readback of a plan produced by the real L08-C
//! planner from the oracle's own effect lines. Tolerance per case is in oracle
//! steps (1 for a single colour pass, 2 for a blur or a short stack, 3 for
//! glow, bilinear taps or a three-pass stack), measured on alpha and on
//! premultiplied colour. Metal readback is never an installed result.
use super::support::{check_case, headless, oracle, parse, run_case, run_group, ORACLE};

#[test]
fn oracle_is_well_formed_and_every_case_has_a_full_expected_image() {
    let oracle = parse(ORACLE);
    assert_eq!(oracle.images.len(), 6);
    assert_eq!(oracle.cases.len(), 24);
    assert_eq!(oracle.mutations.len(), 7);
    for case in &oracle.cases {
        let image = oracle.image(&case.image);
        assert_eq!(case.expect.len(), image.bytes.len(), "{}", case.name);
        assert!(!case.effects.is_empty(), "{}", case.name);
        assert!(matches!(case.tol, 1..=3), "{}", case.name);
        assert!(case.passes >= 1, "{}", case.name);
    }
    let names: std::collections::HashSet<&str> =
        oracle.cases.iter().map(|c| c.name.as_str()).collect();
    assert_eq!(names.len(), oracle.cases.len(), "case names are unique");
    let count = |prefix: &str| {
        oracle
            .cases
            .iter()
            .filter(|c| c.name.starts_with(prefix))
            .count()
    };
    assert_eq!(count("color-adjust-"), 4);
    assert_eq!(count("vignette-"), 3);
    assert_eq!(count("blur-"), 7);
    assert_eq!(count("glow-"), 2);
    assert_eq!(count("stack-"), 8);
    // Both entry variants and both landing buffers are exercised.
    assert!(oracle.cases.iter().any(|c| c.into) && oracle.cases.iter().any(|c| !c.into));
}

#[test]
fn oracle_header_pins_the_baseline_sources() {
    for pin in [
        "# baseline commit fbe4b8a33e6d5a229f014154df2ba21988a9fabc",
        "# sha256 blend.wgsl (whole) = b928fda02ee59558fffc226e9edfe3fbe24949b2d2e3d097b428987b17691ded",
        "# sha256 blur.wgsl (whole) = 05f6337233ca1219964113f1c012877d84cfed2e715a1e4c987ae606eb342145",
        "# sha256 color_adjust.wgsl (whole) = 0dc722f4bf896a5b9321b0ab68875901d44eb8bec82b064673d02c4f19f5e874",
        "# sha256 vignette.wgsl (whole) = 69559256655123fad9aa30e4aa8aec807d9a2fe943ddb4a7090b0b717af85226",
        "# sha256 engine.rs run_one_effect = 73dd19b62c113e0448e227eddf0adb09a09d1bd5dd698923f756e761dcd1caaf",
        "# sha256 geometry-wasm/src/engine.rs (whole) = 1a5e3729dc57922e9c91aa8d4782572f920bc291de331332f4b03b2a27f1cc64",
    ] {
        assert!(ORACLE.lines().any(|line| line == pin), "{pin}");
    }
}

#[test]
fn gpu_colour_adjust_matches_the_baseline_oracle() {
    assert_eq!(run_group("color-adjust-"), 4);
}

#[test]
fn gpu_vignette_matches_the_baseline_oracle() {
    assert_eq!(run_group("vignette-"), 3);
}

#[test]
fn gpu_blur_matches_the_baseline_oracle() {
    assert_eq!(run_group("blur-"), 7);
}

#[test]
fn gpu_glow_matches_the_baseline_oracle() {
    assert_eq!(run_group("glow-"), 2);
}

#[test]
fn gpu_stacks_follow_the_plan_order_landing_and_entry_variant() {
    assert_eq!(run_group("stack-"), 8);
}

#[test]
fn gpu_one_compositor_runs_every_case_repeatedly_with_identical_pixels() {
    // The kernels are built once and shared; a second pass over the same
    // compositor must reproduce the first byte for byte.
    let mut gpu = headless();
    let oracle = oracle();
    let first: Vec<Vec<u8>> = oracle
        .cases
        .iter()
        .map(|case| run_case(&mut gpu, case, oracle.image(&case.image)).bytes)
        .collect();
    for (case, before) in oracle.cases.iter().zip(&first) {
        let image = oracle.image(&case.image);
        let again = run_case(&mut gpu, case, image).bytes;
        assert_eq!(&again, before, "{} is not repeatable", case.name);
        check_case(case, image.w, &again).unwrap();
    }
}
